// TestArchiveEncodingRejectsInvalidMaterial ensures encode validates the
// whole material and hands back no bytes on failure.
func TestArchiveEncodingRejectsInvalidMaterial(t *testing.T) {
	s := NewStore()
	s.Publish("acme", 0, []Policy{allowPolicy("p1", "u1", "read", "org/a", false)})
	s.Decide("acme", request("acme", "u1", "r1", "org/a", "read"))
	s.Publish("acme", 1, nil)
	recs, cp, err := s.AuditExport("acme", 0)
	if err != nil {
		t.Fatal(err)
	}

	if b, err := EncodeAuditArchive("", recs, cp); !errors.Is(err, ErrMissingOrganization) || b != nil {
		t.Fatalf("empty org: bytes=%v err=%v", b, err)
	}

	bad := func(mutate func([]AuditRecord) []AuditRecord, checkpoint Checkpoint) {
		t.Helper()
		rs := cloneExportedRecords(recs)
		rs = mutate(rs)
		b, err := EncodeAuditArchive("acme", rs, checkpoint)
		if !errors.Is(err, ErrInvalidRange) || b != nil {
			t.Fatalf("encode bad material: bytes=%v err=%v, want ErrInvalidRange", b, err)
		}
	}
	bad(func(r []AuditRecord) []AuditRecord { return r[1:] }, cp)                       // missing beginning
	bad(func(r []AuditRecord) []AuditRecord { return r[:2] }, cp)                       // checkpoint past material
	bad(func(r []AuditRecord) []AuditRecord { r[0], r[1] = r[1], r[0]; return r }, cp)  // reordered
	bad(func(r []AuditRecord) []AuditRecord { r[2].Change.Version = 99; return r }, cp) // later record changed
	bad(func(r []AuditRecord) []AuditRecord { return r },
		Checkpoint{Org: "acme", EndSeq: cp.EndSeq, Fingerprint: cp.Fingerprint + "x"}) // bad checkpoint
	bad(func(r []AuditRecord) []AuditRecord { return r },
		Checkpoint{Org: "globex", EndSeq: cp.EndSeq, Fingerprint: cp.Fingerprint}) // foreign checkpoint org

	// A record from another organization, even fingerprint-correct for it.
	foreign := syntheticRecord("globex", 1, AuditDecision, nil, &DecisionRecord{
		Request:  request("globex", "u1", "r1", "org/a", "read"),
		Decision: Decision{Allowed: false, Version: 0},
	}, genesisFingerprint("globex"))
	mixed := cloneExportedRecords(recs)
	mixed[2] = foreign
	if b, err := EncodeAuditArchive("acme", mixed, cp); !errors.Is(err, ErrInvalidRange) || b != nil {
		t.Fatalf("foreign record encode: bytes=%v err=%v", b, err)
	}

	// A well-fingerprinted record whose payload does not match its kind.
	wrongPayload := syntheticRecord("acme", 1, AuditDecision, &PolicyChange{Version: 1}, nil, genesisFingerprint("acme"))
	if b, err := EncodeAuditArchive("acme", []AuditRecord{wrongPayload},
		Checkpoint{Org: "acme", EndSeq: 1, Fingerprint: wrongPayload.Fingerprint}); !errors.Is(err, ErrInvalidRange) || b != nil {
		t.Fatalf("payload/kind mismatch: bytes=%v err=%v", b, err)
	}
}

// reframe parses one archive frame, lets the test alter the payload, and
// rebuilds a frame with a consistent declared length and checksum so the
// failure under test is content validation, not framing.
func reframe(t *testing.T, archive []byte, mutate func(payload []byte) []byte) []byte {
	t.Helper()
	magicLen := len(archiveMagic)
	n := int(binary.BigEndian.Uint32(archive[magicLen : magicLen+4]))
	payload := append([]byte(nil), archive[magicLen+4:magicLen+4+n]...)
	payload = mutate(payload)
	out := append([]byte(nil), archiveMagic...)
	var lb [4]byte
	binary.BigEndian.PutUint32(lb[:], uint32(len(payload)))
	out = append(out, lb[:]...)
	out = append(out, payload...)
	sum := sha256.Sum256(payload)
	out = append(out, sum[:]...)
	return out
}

// TestArchiveDecodeFramingErrors covers every framing failure mode.
func TestArchiveDecodeFramingErrors(t *testing.T) {
	s := NewStore()
	s.Publish("acme", 0, []Policy{allowPolicy("p1", "u1", "read", "org/a", false)})
	s.Decide("acme", request("acme", "u1", "r1", "org/a", "read"))
	recs, cp, err := s.AuditExport("acme", 0)
	if err != nil {
		t.Fatal(err)
	}
	good, err := EncodeAuditArchive("acme", recs, cp)
	if err != nil {
		t.Fatal(err)
	}

	mustFail := func(name string, data []byte) {
		t.Helper()
		got, err := DecodeAuditArchive(data, "acme", cp)
		if !errors.Is(err, ErrInvalidArchive) || got != nil {
			t.Fatalf("%s: records=%v err=%v, want ErrInvalidArchive and no records", name, got, err)
		}
	}
	mustFail("nil", nil)
	mustFail("empty", []byte{})
	mustFail("garbage", []byte("this is certainly not an audit archive"))
	mustFail("almost magic", append([]byte(archiveMagic[:len(archiveMagic)-1]), 'x'))
	// Truncations at every boundary class.
	for _, cut := range []int{1, 4, 31, 32, 33, len(archiveMagic), len(archiveMagic) + 1, len(good) - 1} {
		if cut < len(good) {
			mustFail(fmt.Sprintf("truncated %d", cut), good[:cut])
		}
	}
	// Flip a byte in the magic.
	flip := append([]byte(nil), good...)
	flip[0] ^= 0x80
	mustFail("bad magic", flip)
	// Declared length beyond the actual file.
	tooLong := append([]byte(nil), good...)
	binary.BigEndian.PutUint32(tooLong[len(archiveMagic):], binary.BigEndian.Uint32(tooLong[len(archiveMagic):])+100)
	mustFail("declared length too large", tooLong)
	// Declared length shorter: bytes of the good frame become trailing.
	tooShort := append([]byte(nil), good...)
	binary.BigEndian.PutUint32(tooShort[len(archiveMagic):], binary.BigEndian.Uint32(tooShort[len(archiveMagic):])-1)
	mustFail("declared length too small", tooShort)
	// Damage inside the payload with the original checksum left intact.
	damaged := append([]byte(nil), good...)
	damaged[len(archiveMagic)+5] ^= 0x01
	mustFail("payload bitflip, stale checksum", damaged)
	// Damage inside the checksum.
	csumDamage := append([]byte(nil), good...)
	csumDamage[len(csumDamage)-1] ^= 0x01
	mustFail("checksum bitflip", csumDamage)
	// A second full archive concatenated to the first is trailing material.
	mustFail("concatenated second archive", append(append([]byte(nil), good...), good...))
	// Ordinary trailing junk.
	mustFail("trailing junk", append(append([]byte(nil), good...), 0, 1, 2, 3))

	// A content change with a recomputed checksum passes framing but must
	// fail chain validation with ErrInvalidRange.
	tampered := reframe(t, good, func(payload []byte) []byte {
		idx := bytes.Index(payload, []byte("matched allow policy"))
		if idx < 0 {
			t.Fatal("fixture reason not found in payload")
		}
		payload[idx] ^= 0x01 // same length, no length prefix or marker moves
		return payload
	})
	if got, err := DecodeAuditArchive(tampered, "acme", cp); !errors.Is(err, ErrInvalidRange) || got != nil {
		t.Fatalf("checksum-valid tampered content: records=%v err=%v, want ErrInvalidRange", got, err)
	}
}

// TestArchiveDecodeContentValidation ensures decode validates the entire
// material against the caller's retained checkpoint and expected org.
func TestArchiveDecodeContentValidation(t *testing.T) {
	s := NewStore()
	s.Publish("acme", 0, []Policy{allowPolicy("p1", "u1", "read", "org/a", false)})
	s.Decide("acme", request("acme", "u1", "r1", "org/a", "read"))
	s.Publish("acme", 1, nil)
	s.Decide("acme", request("acme", "late-victim", "r1", "org/a", "read"))
	recs, cp, err := s.AuditExport("acme", 0)
	if err != nil {
		t.Fatal(err)
	}
	good, err := EncodeAuditArchive("acme", recs, cp)
	if err != nil {
		t.Fatal(err)
	}

	if got, err := DecodeAuditArchive(good, "", cp); !errors.Is(err, ErrMissingOrganization) || got != nil {
		t.Fatalf("empty org decode: %v %v", got, err)
	}
	if _, err := DecodeAuditArchive(good, "globex", cp); !errors.Is(err, ErrInvalidRange) {
		t.Fatalf("foreign expected org err = %v", err)
	}
	// The caller's checkpoint is authoritative; a wrong fingerprint and a
	// wrong end sequence both fail, even though the embedded checkpoint
	// matches the content.
	for _, wrong := range []Checkpoint{
		{Org: "acme", EndSeq: cp.EndSeq, Fingerprint: cp.Fingerprint + "x"},
		{Org: "acme", EndSeq: cp.EndSeq - 1, Fingerprint: cp.Fingerprint},
		{Org: "acme", EndSeq: cp.EndSeq, Fingerprint: genesisFingerprint("acme")},
	} {
		if _, err := DecodeAuditArchive(good, "acme", wrong); !errors.Is(err, ErrInvalidRange) {
			t.Fatalf("checkpoint %+v err = %v, want ErrInvalidRange", wrong, err)
		}
	}

	// Damage confined to a record after the one the caller plans to review
	// still fails the whole read.
	late := reframe(t, good, func(payload []byte) []byte {
		idx := bytes.Index(payload, []byte("late-victim"))
		if idx < 0 {
			t.Fatal("late record subject not found in payload")
		}
		payload[idx] ^= 0x01
		return payload
	})
	if _, err := DecodeAuditArchive(late, "acme", cp); !errors.Is(err, ErrInvalidRange) {
		t.Fatalf("late-record damage err = %v, want ErrInvalidRange", err)
	}

	// An archive of another organization cannot be read as acme even with
	// acme-shaped caller data.
	grecs, gcp, _ := NewStore().AuditExport("globex", 0)
	garchive, err := EncodeAuditArchive("globex", grecs, gcp)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := DecodeAuditArchive(garchive, "acme", cp); !errors.Is(err, ErrInvalidRange) {
		t.Fatalf("cross-org archive err = %v", err)
	}
}

// TestArchiveCheckpointInsideIsNotAuthority proves a file that internally
// carries one checkpoint still validates exclusively against the caller's.
func TestArchiveCheckpointInsideIsNotAuthority(t *testing.T) {
	s := NewStore()
	s.Publish("acme", 0, []Policy{allowPolicy("p1", "u1", "read", "org/a", false)})
	s.Decide("acme", request("acme", "u1", "r1", "org/a", "read"))
	recs, cp, _ := s.AuditExport("acme", 0)
	good, err := EncodeAuditArchive("acme", recs, cp)
	if err != nil {
		t.Fatal(err)
	}

	// Re-frame the same records with a different embedded end sequence: the
	// caller's retained checkpoint must be the one that decides.
	rewritten := reframe(t, good, func(payload []byte) []byte {
		// Header layout: u32 orgLen, org, u32 endSeq, u32 fpLen, fp, ...
		pos := 4 + len("acme")
		binary.BigEndian.PutUint32(payload[pos:pos+4], 999)
		return payload
	})
	if _, err := DecodeAuditArchive(rewritten, "acme", cp); !errors.Is(err, ErrInvalidRange) {
		t.Fatalf("altered embedded metadata must not be trusted: err = %v", err)
	}
}

// TestArchiveInconsistentDecisionIsNotArchiveDamage archives a chain that
// is internally valid but whose recorded decision contradicts the recorded
// policy: decode succeeds, and offline review reports the inconsistency.
func TestArchiveInconsistentDecisionIsNotArchiveDamage(t *testing.T) {
	req := request("acme", "u1", "r1", "org/a", "read")
	recs, cp := syntheticChain("acme", []func(int) (string, *PolicyChange, *DecisionRecord){
		func(seq int) (string, *PolicyChange, *DecisionRecord) {
			return AuditPolicyChange, &PolicyChange{
				Version:  1,
				Policies: []Policy{allowPolicy("p1", "u1", "read", "org/a", false)},
			}, nil
		},
		func(seq int) (string, *PolicyChange, *DecisionRecord) {
			return AuditDecision, nil, &DecisionRecord{
				Request:  req,
				Decision: Decision{Allowed: false, Reason: "matched deny policy", Matched: []string{"p1"}, Version: 1},
			}
		},
	})
	archive, err := EncodeAuditArchive("acme", recs, cp)
	if err != nil {
		t.Fatal(err)
	}
	got, err := DecodeAuditArchive(archive, "acme", cp)
	if err != nil {
		t.Fatalf("a decision disagreement is not archive damage: %v", err)
	}
	review, err := RecheckDecisionOffline("acme", got, cp, 2)
	if err != nil {
		t.Fatal(err)
	}
	if review.Consistent {
		t.Fatal("inconsistent decision must still be reported by offline review")
	}
}

// TestArchiveIsReadOnlyAndDetached proves encode and decode mutate nothing
// and return values independent of their inputs and of each other.
func TestArchiveIsReadOnlyAndDetached(t *testing.T) {
	s := NewStore()
	s.Publish("acme", 0, []Policy{allowPolicy("p1", "u1", "read", "org/a", false)})
	s.Decide("acme", request("acme", "u1", "r1", "org/a", "read"))
	before, beforeCP, _ := s.AuditExport("acme", 0)

	recs, cp, _ := s.AuditExport("acme", 0)
	snapshot := cloneExportedRecords(recs)
	archive, err := EncodeAuditArchive("acme", recs, cp)
	if err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(recs, snapshot) {
		t.Fatal("encode mutated the supplied records")
	}
	// Encode/decode append nothing to any service state.
	after, afterCP, _ := s.AuditExport("acme", 0)
	if !reflect.DeepEqual(after, before) || afterCP != beforeCP {
		t.Fatal("archive operations changed service state")
	}

	got, err := DecodeAuditArchive(archive, "acme", cp)
	if err != nil {
		t.Fatal(err)
	}
	// Mutating the input bytes after decode cannot reach a prior result.
	for i := range archive {
		archive[i] = 0
	}
	if got[0].Change.Policies[0].ID != "p1" {
		t.Fatal("decoded records alias the archive input bytes")
	}
	// Mutating one decoded result cannot affect a later decode.
	got[0].Change.Policies[0].ID = "hacker"
	got[1].Decision.Request.Subject.ID = "hacker"
	got[1].Decision.Decision.Matched = append(got[1].Decision.Decision.Matched, "x")
	fresh, err := EncodeAuditArchive("acme", recs, cp)
	if err != nil {
		t.Fatal(err)
	}
	again, err := DecodeAuditArchive(fresh, "acme", cp)
	if err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(again, recs) {
		t.Fatal("mutation of one decoded result reached another decode")
	}
}

// TestArchiveRoundTripAfterInstanceEnds simulates the stated lifecycle:
// export and archive on one instance, then (with no Store at all) read the
// bytes elsewhere and continue offline review against the retained
// checkpoint.
func TestArchiveRoundTripAfterInstanceEnds(t *testing.T) {
	first := NewStore()
	first.Publish("acme", 0, []Policy{
		{ID: "p1", Subject: "u1", Action: "read", Scope: "org/a", Effect: EffectAllow, ResourceID: " r 1 "},
	})
	original := first.Decide("acme", request("acme", "u1", " r 1 ", "org/a", "read"))
	recs, cp, err := first.AuditExport("acme", 0)
	if err != nil {
		t.Fatal(err)
	}
	saved, err := EncodeAuditArchive("acme", recs, cp)
	if err != nil {
		t.Fatal(err)
	}

	// New instance, no Store involved in decoding.
	loaded, err := DecodeAuditArchive(saved, "acme", cp)
	if err != nil {
		t.Fatalf("read after instance end: %v", err)
	}
	review, err := RecheckDecisionOffline("acme", loaded, cp, 2)
	if err != nil {
		t.Fatal(err)
	}
	if !review.Consistent || !reflect.DeepEqual(review.Original, original) {
		t.Fatalf("post-restart review = %+v, original %+v", review, original)
	}
}

// This file pins down the decoder's handling of corrupted *internal list
// lengths*: archives whose outer framing, declared payload length and
// checksum are all correct, but where a count declared inside the payload
// cannot be satisfied by the bytes that follow. Three lists carry counts:
// the material's record list, a policy change's policy list, and the string
// lists used for subject roles and matched policies.
//
// Every corruption below is reframed with a consistent outer length and
// checksum, so exercising these cases proves the protection comes from
// decoding the payload's own structure rather than from the framing-level
// samples in audit_archive_test.go. A count the body cannot satisfy, a
// count word cut off mid-read, and a complete early item followed by an
// incomplete later item are all unreadable archives: DecodeAuditArchive
// must return ErrInvalidArchive (matched by errors.Is) and nil records,
// never a prefix and never a crash or hostile allocation.
package darksafe

import (
	"bytes"
	"crypto/sha256"
	"encoding/binary"
	"errors"
	"reflect"
	"runtime"
	"strings"
	"testing"
)

// listSite locates one length-counted list inside a payload, in payload
// byte offsets. itemEnds marks the byte just past each complete item.
type listSite struct {
	markerAt int
	countAt  int // -1 when the list is encoded nil
	itemEnds []int
}

// payloadInspector walks the known-good, two-record fixture payload in
// encode order. It exists only to locate the bytes a test corrupts; it
// mirrors archiveWriter, so a format change moves these tests off their
// target rather than silently corrupting the wrong field.
type payloadInspector struct {
	b   []byte
	pos int
}

func (c *payloadInspector) u32() int {
	v := int(binary.BigEndian.Uint32(c.b[c.pos : c.pos+4]))
	c.pos += 4
	return v
}

func (c *payloadInspector) str() {
	n := c.u32()
	c.pos += n
}

func (c *payloadInspector) marker() byte {
	m := c.b[c.pos]
	c.pos++
	return m
}

func (c *payloadInspector) stringListSite() listSite {
	s := listSite{markerAt: c.pos, countAt: -1}
	if c.marker() == archiveTagNil {
		return s
	}
	s.countAt = c.pos
	n := c.u32()
	s.itemEnds = make([]int, 0, n)
	for i := 0; i < n; i++ {
		c.str()
		s.itemEnds = append(s.itemEnds, c.pos)
	}
	return s
}

func (c *payloadInspector) policySite() {
	c.str() // ID
	c.str() // Subject
	c.str() // Action
	c.str() // Scope
	c.str() // Effect
	c.pos++ // Recursive bool
	c.str() // ResourceID
}

func (c *payloadInspector) policyListSite() listSite {
	s := listSite{markerAt: c.pos, countAt: -1}
	if c.marker() == archiveTagNil {
		return s
	}
	s.countAt = c.pos
	n := c.u32()
	s.itemEnds = make([]int, 0, n)
	for i := 0; i < n; i++ {
		c.policySite()
		s.itemEnds = append(s.itemEnds, c.pos)
	}
	return s
}

// inspectTwoRecordPayload locates the four counted lists in the fixture
// built by listCorruptionFixture.
func inspectTwoRecordPayload(t *testing.T, p []byte) fixtureSites {
	t.Helper()
	c := &payloadInspector{b: p}
	c.str()    // embedded org
	c.pos += 4 // embedded end sequence
	c.str()    // embedded checkpoint fingerprint
	records := listSite{countAt: c.pos}
	n := c.u32() // record count
	if n != 2 {
		t.Fatalf("fixture record count = %d, want 2", n)
	}

	// Record 1: policy change with two policies, absent decision.
	c.str()    // org
	c.pos += 4 // seq
	c.str()    // kind
	if m := c.marker(); m != archiveTagPresent {
		t.Fatalf("record 1 change marker = %d, want present", m)
	}
	c.pos += 4 // change version
	policies := c.policyListSite()
	c.pos += 4 // source version
	c.pos++    // rolled back bool
	if m := c.marker(); m != archiveTagNil {
		t.Fatalf("record 1 decision marker = %d, want nil", m)
	}
	c.str() // prev fingerprint
	c.str() // own fingerprint
	records.itemEnds = append(records.itemEnds, c.pos)

	// Record 2: decision with two roles and two matched policies.
	c.str()    // org
	c.pos += 4 // seq
	c.str()    // kind
	if m := c.marker(); m != archiveTagNil {
		t.Fatalf("record 2 change marker = %d, want nil", m)
	}
	if m := c.marker(); m != archiveTagPresent {
		t.Fatalf("record 2 decision marker = %d, want present", m)
	}
	c.str() // request SubjectOrg
	c.str() // request ResourceOrg
	c.str() // subject ID
	c.str() // subject Kind
	roles := c.stringListSite()
	c.pos++ // subject disabled bool
	c.str() // resource ID
	c.str() // resource scope
	c.str() // action
	c.pos++ // decision allowed bool
	c.str() // decision reason
	matched := c.stringListSite()
	c.pos += 4 // decision version
	c.str()    // prev fingerprint
	c.str()    // own fingerprint
	records.itemEnds = append(records.itemEnds, c.pos)

	if c.pos != len(p) {
		t.Fatalf("inspector ended at %d, payload length %d", c.pos, len(p))
	}
	if len(roles.itemEnds) != 2 || len(matched.itemEnds) != 2 || len(policies.itemEnds) != 2 {
		t.Fatalf("fixture lists must each hold 2 items: policies=%d roles=%d matched=%d",
			len(policies.itemEnds), len(roles.itemEnds), len(matched.itemEnds))
	}
	return fixtureSites{records: records, policies: policies, roles: roles, matched: matched}
}

// fixtureSites are the four counted lists in the two-record fixture.
type fixtureSites struct {
	records  listSite
	policies listSite
	roles    listSite
	matched  listSite
}

// framePayload wraps a (possibly corrupted) payload with correct outer
// framing, declared length and checksum, so the failure under test is
// always internal list decoding rather than framing.
func framePayload(payload []byte) []byte {
	out := append([]byte(nil), archiveMagic...)
	var lb [4]byte
	binary.BigEndian.PutUint32(lb[:], uint32(len(payload)))
	out = append(out, lb[:]...)
	out = append(out, payload...)
	sum := sha256.Sum256(payload)
	return append(out, sum[:]...)
}

// payloadOf extracts a copy of one archive's payload.
func payloadOf(t *testing.T, archive []byte) []byte {
	t.Helper()
	magicLen := len(archiveMagic)
	n := int(binary.BigEndian.Uint32(archive[magicLen : magicLen+4]))
	return append([]byte(nil), archive[magicLen+4:magicLen+4+n]...)
}

// listCorruptionFixture builds complete, valid material: one policy change
// carrying two policies followed by one decision whose subject has two
// roles and whose decision matched two policies. All four counted lists
// therefore hold real, multi-item content.
func listCorruptionFixture(t *testing.T) ([]byte, []AuditRecord, Checkpoint) {
	t.Helper()
	s := NewStore()
	s.Publish("acme", 0, []Policy{
		allowPolicy("p1", "u1", "read", "org/a", false),
		allowPolicy("p2", "u1", "read", "org/a", false),
	})
	req := OrgRequest{
		SubjectOrg:  "acme",
		ResourceOrg: "acme",
		Subject:     Subject{ID: "u1", Roles: []string{"role-a", "role-b"}},
		Resource:    Resource{ID: "r1", Scope: "org/a"},
		Action:      "read",
	}
	original := s.Decide("acme", req)
	recs, cp, err := s.AuditExport("acme", 0)
	if err != nil {
		t.Fatal(err)
	}
	archive, err := EncodeAuditArchive("acme", recs, cp)
	if err != nil {
		t.Fatal(err)
	}
	got, err := DecodeAuditArchive(archive, "acme", cp)
	if err != nil {
		t.Fatalf("fixture must decode: %v", err)
	}
	review, err := RecheckDecisionOffline("acme", got, cp, 2)
	if err != nil || !review.Consistent || !reflect.DeepEqual(review.Original, original) {
		t.Fatalf("fixture review = %+v, %v", review, err)
	}
	return archive, recs, cp
}

// TestArchiveInternalListCountCorruption covers, for every counted list,
// the shapes that make a payload unreadable: a declared count the
// remaining bytes cannot satisfy, a count word cut off mid-read, and a
// complete early item followed by a later item missing a required field.
// All arrive with valid outer framing and checksum and must be reported as
// ErrInvalidArchive with nil records — even when a complete, readable
// prefix (a full policy change and decision) precedes the damage.
func TestArchiveInternalListCountCorruption(t *testing.T) {
	good, _, cp := listCorruptionFixture(t)
	basePayload := payloadOf(t, good)
	sites := inspectTwoRecordPayload(t, basePayload)

	// expectInvalid runs one payload mutation and asserts the whole read
	// fails as an unreadable archive without delivering the intact prefix.
	// It also proves the failed call rewrites neither its input bytes nor
	// the retained checkpoint handed to it.
	expectInvalid := func(name, wantSubstr string, mutate func(p []byte) []byte) {
		t.Helper()
		payload := mutate(append([]byte(nil), basePayload...))
		data := framePayload(payload)
		dataSnapshot := append([]byte(nil), data...)
		cpSnapshot := cp

		got, err := DecodeAuditArchive(data, "acme", cp)
		if !errors.Is(err, ErrInvalidArchive) {
			t.Fatalf("%s: err = %v, want ErrInvalidArchive", name, err)
		}
		if errors.Is(err, ErrInvalidRange) {
			t.Fatalf("%s: structurally unreadable list counted as a content error: %v", name, err)
		}
		if got != nil {
			t.Fatalf("%s: returned %d records on a damaged list, want nil", name, len(got))
		}
		if wantSubstr != "" && !strings.Contains(err.Error(), wantSubstr) {
			t.Fatalf("%s: err = %q, want substring %q", name, err.Error(), wantSubstr)
		}
		if !bytes.Equal(data, dataSnapshot) {
			t.Fatalf("%s: failed decode rewrote the archive bytes", name)
		}
		if cp != cpSnapshot {
			t.Fatalf("%s: failed decode rewrote the checkpoint", name)
		}
	}

	lists := []struct {
		name     string
		site     listSite
		minBytes int
	}{
		{"records", sites.records, 22},
		{"policies", sites.policies, 6*4 + 1},
		{"roles", sites.roles, 4},
		{"matched", sites.matched, 4},
	}

	for _, l := range lists {
		// A) The count word is intact but promises more items than the bytes
		// left could ever hold. Rewrite only the count (payload length
		// unchanged): the read must fail as an unreadable archive, whether
		// the per-item floor rejects the count up front or reading the
		// missing items truncates — the error class is what the caller uses.
		//
		// This count value is the smallest one whose floor exceeds the
		// remaining bytes, computed from this fixture's real offsets.
		overCount := (len(basePayload)-(l.site.countAt+4))/l.minBytes + 1
		expectInvalid(l.name+": count exceeds remaining items", "",
			func(p []byte) []byte {
				binary.BigEndian.PutUint32(p[l.site.countAt:], uint32(overCount))
				return p
			})

		// The maximum uint32 count on this small body must fail with the
		// same deterministic error for every counted list, not just the
		// record list, and without enumerating (or provisioning) the
		// phantom items.
		expectInvalid(l.name+": max uint32 count on small body", "implausible list count",
			func(p []byte) []byte {
				binary.BigEndian.PutUint32(p[l.site.countAt:], 0xffffffff)
				return p
			})

		// C) Every early item is whole; the final item is missing its last
		// required field by one byte. Enough bytes remain to pass the coarse
		// per-item count floor, so this failure must surface while reading
		// that item — proving the item-level truncation guard, not only the
		// count bound, is in place.
		lastItemEnd := l.site.itemEnds[len(l.site.itemEnds)-1]
		expectInvalid(l.name+": later item missing required field", "truncated archive payload",
			func(p []byte) []byte { return p[:lastItemEnd-1] })
	}

	// B) A count word physically cut off mid-read. For the three inner
	// lists this needs a one-record payload: the outer record-count floor
	// (22 bytes per record) must still pass so the reader actually reaches
	// the inner list and proves its own u32 truncation guard.
	inner := buildInnerListCountTruncationPayloads(t)
	cutCountWord := func(name string, full []byte, countAt int) {
		t.Helper()
		// These are single-record payloads, so the outer record-count floor
		// (22 bytes/record) still passes at this cut; the reader must reach
		// the inner list and prove its own count-word truncation guard.
		cut := countAt + 2
		data := framePayload(full[:cut])
		got, err := DecodeAuditArchive(data, "acme", cp)
		if !errors.Is(err, ErrInvalidArchive) || got != nil {
			t.Fatalf("%s: records=%v err=%v, want ErrInvalidArchive, nil", name, got, err)
		}
		if !strings.Contains(err.Error(), "truncated archive payload") {
			t.Fatalf("%s: err = %q, want a mid-read count truncation", name, err)
		}
	}
	cutCountWord("policies count word", inner.policiesPayload, inner.policiesCountAt)
	cutCountWord("roles count word", inner.rolesPayload, inner.rolesCountAt)
	cutCountWord("matched count word", inner.matchedPayload, inner.matchedCountAt)

	// B for the outer record list: header complete, its count word cut.
	headerOnly := buildArchiveHeader(t)
	recordCountCut := append(append([]byte(nil), headerOnly...), 0x00, 0x00)
	if got, err := DecodeAuditArchive(framePayload(recordCountCut), "acme", cp); !errors.Is(err, ErrInvalidArchive) || got != nil {
		t.Fatalf("records count word: records=%v err=%v, want ErrInvalidArchive, nil", got, err)
	}

	// A dedicated emphasis for the requirement: a tiny archive declaring
	// 4294967295 records must return the deterministic error promptly,
	// without crashing or provisioning as if the count were real.
	w := &archiveWriter{}
	w.stringField("acme")
	w.u32(0)
	w.stringField("g")
	w.u32(0xffffffff)
	if w.err != nil {
		t.Fatal(w.err)
	}
	tinyHuge := framePayload(w.buf)

	var before, after runtime.MemStats
	runtime.GC()
	runtime.ReadMemStats(&before)
	got, err := DecodeAuditArchive(tinyHuge, "acme", cp)
	runtime.ReadMemStats(&after)
	if !errors.Is(err, ErrInvalidArchive) || got != nil {
		t.Fatalf("tiny archive with max count: records=%v err=%v, want ErrInvalidArchive, nil", got, err)
	}
	if !strings.Contains(err.Error(), "implausible list count") {
		t.Fatalf("tiny archive with max count: err = %q, want count-bound rejection", err)
	}
	// A regression that trusted the count would try to provision billions
	// of records; bound what this error path may allocate.
	if alloc := after.TotalAlloc - before.TotalAlloc; alloc > 16<<20 {
		t.Fatalf("max-count decode allocated %d bytes, want a small error path", alloc)
	}
}

// innerListTruncation holds one complete one-record payload and the offset
// of a targeted inner list's count word.
type innerListTruncation struct {
	policiesPayload              []byte
	policiesCountAt              int
	rolesPayload, matchedPayload []byte
	rolesCountAt                 int
	matchedCountAt               int
}

// buildInnerListCountTruncationPayloads hand-builds structurally complete
// one-record payloads (fingerprints are irrelevant here because a truncated
// count fails format decoding before any content check) and reports the
// offset of each inner list's count word.
func buildInnerListCountTruncationPayloads(t *testing.T) innerListTruncation {
	t.Helper()
	var out innerListTruncation

	// One policy-change record whose policy list carries two policies.
	{
		w := &archiveWriter{}
		w.stringField("acme")
		w.u32(1)
		w.stringField("g")
		w.u32(1) // one record
		w.stringField("acme")
		w.u32(1)
		w.stringField(AuditPolicyChange)
		w.raw([]byte{archiveTagPresent}) // change present
		w.u32(1)                         // change version
		w.raw([]byte{archiveTagPresent}) // policy list present
		out.policiesCountAt = len(w.buf)
		w.u32(2)
		w.policy(allowPolicy("p1", "u1", "read", "org/a", false))
		w.policy(allowPolicy("p2", "u1", "read", "org/a", false))
		w.u32(0)           // source version
		w.boolean(false)   // rolled back
		w.raw(nilMarker()) // decision absent
		w.stringField("p") // prev fingerprint
		w.stringField("f") // own fingerprint
		if w.err != nil {
			t.Fatal(w.err)
		}
		out.policiesPayload = w.buf
	}

	// One decision record whose subject roles and decision matched list
	// each carry two strings.
	{
		w := &archiveWriter{}
		w.stringField("acme")
		w.u32(1)
		w.stringField("g")
		w.u32(1) // one record
		w.stringField("acme")
		w.u32(1)
		w.stringField(AuditDecision)
		w.raw([]byte{archiveTagNil})     // change absent
		w.raw([]byte{archiveTagPresent}) // decision present
		w.stringField("acme")            // SubjectOrg
		w.stringField("acme")            // ResourceOrg
		w.stringField("u1")              // subject ID
		w.stringField("user")            // subject kind
		w.raw([]byte{archiveTagPresent}) // roles present
		out.rolesCountAt = len(w.buf)
		w.u32(2)
		w.stringField("role-a")
		w.stringField("role-b")
		w.boolean(false) // subject disabled
		w.stringField("r1")
		w.stringField("org/a")
		w.stringField("read") // action
		w.boolean(true)       // decision allowed
		w.stringField("matched allow policy")
		w.raw([]byte{archiveTagPresent}) // matched present
		out.matchedCountAt = len(w.buf)
		w.u32(2)
		w.stringField("p1")
		w.stringField("p2")
		w.u32(1)           // decision version
		w.stringField("p") // prev fingerprint
		w.stringField("f") // own fingerprint
		if w.err != nil {
			t.Fatal(w.err)
		}
		out.rolesPayload = w.buf
		out.matchedPayload = w.buf
	}
	return out
}

// nilMarker returns the one-byte absent/nil marker as a slice.
func nilMarker() []byte { return []byte{archiveTagNil} }

// buildArchiveHeader writes just the payload header (embedded org, end
// sequence and checkpoint fingerprint) that precedes the record count.
func buildArchiveHeader(t *testing.T) []byte {
	t.Helper()
	w := &archiveWriter{}
	w.stringField("acme")
	w.u32(0)
	w.stringField("g")
	if w.err != nil {
		t.Fatal(w.err)
	}
	return w.buf
}

// TestArchiveLaterRecordListDamageDiscardsPrefix is the record-level case
// the requirement names: a complete policy change and a complete decision
// have already been read when a *later* record's inner list turns out to
// promise items its bytes cannot provide. The whole read must fail and the
// intact prefix must never be handed to the caller.
func TestArchiveLaterRecordListDamageDiscardsPrefix(t *testing.T) {
	thirdReason := "third-decision-reason-7f3a"
	recs, cp := syntheticChain("acme", []func(int) (string, *PolicyChange, *DecisionRecord){
		func(seq int) (string, *PolicyChange, *DecisionRecord) {
			return AuditPolicyChange, &PolicyChange{
				Version: 1, Policies: []Policy{allowPolicy("p1", "u1", "read", "org/a", false)},
			}, nil
		},
		func(seq int) (string, *PolicyChange, *DecisionRecord) {
			return AuditDecision, nil, &DecisionRecord{
				Request:  request("acme", "u1", "r1", "org/a", "read"),
				Decision: Decision{Allowed: true, Reason: "matched allow policy", Matched: []string{"p1"}, Version: 1},
			}
		},
		func(seq int) (string, *PolicyChange, *DecisionRecord) {
			return AuditDecision, nil, &DecisionRecord{
				Request:  request("acme", "u1", "r1", "org/a", "read"),
				Decision: Decision{Allowed: false, Reason: thirdReason, Matched: []string{"p1"}, Version: 1},
			}
		},
	})
	good, err := EncodeAuditArchive("acme", recs, cp)
	if err != nil {
		t.Fatalf("encode: %v", err)
	}

	// The third record's matched list follows its unique reason string:
	// reason stringField bytes, then one list marker, then its count word.
	damaged := reframe(t, good, func(payload []byte) []byte {
		idx := bytes.Index(payload, []byte(thirdReason))
		if idx < 0 {
			t.Fatal("third-record reason not found")
		}
		if bytes.Index(payload[idx+1:], []byte(thirdReason)) >= 0 {
			t.Fatal("third-record reason must be unique for an unambiguous locate")
		}
		countAt := idx + len(thirdReason) + 1 // skip reason bytes and the list marker
		binary.BigEndian.PutUint32(payload[countAt:], 0xffffffff)
		return payload
	})

	got, err := DecodeAuditArchive(damaged, "acme", cp)
	if !errors.Is(err, ErrInvalidArchive) || got != nil {
		t.Fatalf("later-record list damage: records=%v err=%v, want ErrInvalidArchive, nil", got, err)
	}
}

// TestArchiveListContentChangeIsNotArchiveDamage keeps format damage
// separate from untrusted content: a single in-list byte flipped with the
// checksum recomputed is fully readable as a format (every length and
// marker intact), so it must fail as content with ErrInvalidRange — not be
// swept into ErrInvalidArchive merely because the byte lives inside a
// policy or string list.
func TestArchiveListContentChangeIsNotArchiveDamage(t *testing.T) {
	good, _, cp := listCorruptionFixture(t)
	payload := payloadOf(t, good)
	sites := inspectTwoRecordPayload(t, payload)

	flipOneListByte := func(name string, site listSite) {
		t.Helper()
		// Flip a byte in the second item's content (past its length word),
		// leaving every length prefix and marker untouched.
		secondItem := site.itemEnds[0]
		tampered := append([]byte(nil), payload...)
		tampered[secondItem+4] ^= 0x01
		data := framePayload(tampered)
		got, err := DecodeAuditArchive(data, "acme", cp)
		if !errors.Is(err, ErrInvalidRange) || got != nil {
			t.Fatalf("%s: records=%v err=%v, want ErrInvalidRange, nil", name, got, err)
		}
		if errors.Is(err, ErrInvalidArchive) {
			t.Fatalf("%s: readable-format content change reported as archive damage", name)
		}
	}
	flipOneListByte("matched list byte", sites.matched)
	flipOneListByte("roles list byte", sites.roles)
	flipOneListByte("policy list byte", sites.policies)
}

// TestArchiveValidListShapesRoundTrip locks the legal boundaries the
// corruption guard must not disturb: nil and non-nil empty policy/string
// lists keep their exact shape, populated lists keep order and raw bytes,
// and neither fingerprints nor the caller checkpoint change. The decoded
// material still verifies and feeds offline review unchanged.
func TestArchiveValidListShapesRoundTrip(t *testing.T) {
	req := request("acme", "u1", "r1", "org/a", "read")
	recs, cp := syntheticChain("acme", []func(int) (string, *PolicyChange, *DecisionRecord){
		// Policy list shapes.
		func(seq int) (string, *PolicyChange, *DecisionRecord) {
			return AuditPolicyChange, &PolicyChange{Version: 1, Policies: nil}, nil
		},
		func(seq int) (string, *PolicyChange, *DecisionRecord) {
			return AuditPolicyChange, &PolicyChange{
				Version: 2, SourceVersion: 1, RolledBack: true, Policies: []Policy{},
			}, nil
		},
		func(seq int) (string, *PolicyChange, *DecisionRecord) {
			return AuditPolicyChange, &PolicyChange{Version: 3, Policies: []Policy{
				// Raw, non-UTF-8 bytes and a fixed order must be preserved.
				{ID: "p" + invalidByte, Subject: "u1", Action: "read", Scope: "org/a", Effect: EffectAllow, ResourceID: "r" + anotherInvalidByte},
				allowPolicy("p2", "u1", "read", "org/a", false),
			}}, nil
		},
		// String list shapes across subject roles and matched policies.
		func(seq int) (string, *PolicyChange, *DecisionRecord) {
			r := req
			r.Subject.Roles = nil
			return AuditDecision, nil, &DecisionRecord{
				Request:  r,
				Decision: Decision{Allowed: true, Reason: "matched allow policy", Matched: nil, Version: 3},
			}
		},
		func(seq int) (string, *PolicyChange, *DecisionRecord) {
			r := req
			r.Subject.Roles = []string{}
			return AuditDecision, nil, &DecisionRecord{
				Request:  r,
				Decision: Decision{Allowed: true, Reason: "matched allow policy", Matched: []string{}, Version: 3},
			}
		},
		func(seq int) (string, *PolicyChange, *DecisionRecord) {
			r := req
			r.Subject.Roles = []string{"zeta", "alpha"} // order is preserved, not sorted
			return AuditDecision, nil, &DecisionRecord{
				Request: r,
				Decision: Decision{Allowed: true, Reason: "matched allow policy",
					Matched: []string{"p" + invalidByte, "p2"}, Version: 3},
			}
		},
	})

	archive, err := EncodeAuditArchive("acme", recs, cp)
	if err != nil {
		t.Fatalf("encode list shapes: %v", err)
	}
	got, err := DecodeAuditArchive(archive, "acme", cp)
	if err != nil {
		t.Fatalf("decode list shapes: %v", err)
	}
	if !reflect.DeepEqual(got, recs) {
		t.Fatalf("valid list shapes changed across the archive:\n got %+v\nwant %+v", got, recs)
	}

	// Explicit nil-vs-empty preservation for both list kinds.
	if got[0].Change.Policies != nil {
		t.Fatal("nil policy list decoded non-nil")
	}
	if got[1].Change.Policies == nil || len(got[1].Change.Policies) != 0 {
		t.Fatal("empty non-nil policy list lost its shape")
	}
	if got[3].Decision.Request.Subject.Roles != nil || got[3].Decision.Decision.Matched != nil {
		t.Fatal("nil string lists decoded non-nil")
	}
	if got[4].Decision.Request.Subject.Roles == nil || got[4].Decision.Decision.Matched == nil {
		t.Fatal("empty non-nil string lists decoded as nil")
	}
	// Populated lists: exact order and raw bytes, including non-UTF-8.
	wantRoles := []string{"zeta", "alpha"}
	if !reflect.DeepEqual(got[5].Decision.Request.Subject.Roles, wantRoles) {
		t.Fatalf("roles order/bytes changed: got %q want %q", got[5].Decision.Request.Subject.Roles, wantRoles)
	}
	wantMatched := []string{"p" + invalidByte, "p2"}
	if !reflect.DeepEqual(got[5].Decision.Decision.Matched, wantMatched) {
		t.Fatalf("matched order/bytes changed: got %q want %q", got[5].Decision.Decision.Matched, wantMatched)
	}
	policies := got[2].Change.Policies
	if policies[0].ID != "p"+invalidByte || policies[0].ResourceID != "r"+anotherInvalidByte {
		t.Fatalf("policy raw bytes changed: id=%q resource=%q", policies[0].ID, policies[0].ResourceID)
	}

	// Fingerprints and the retained checkpoint are untouched, and the
	// material remains directly usable by offline verification.
	for i := range got {
		if got[i].Fingerprint != recs[i].Fingerprint {
			t.Fatalf("record %d fingerprint changed", i+1)
		}
	}
	if err := VerifyAudit("acme", got, cp); err != nil {
		t.Fatalf("decoded valid-list material must verify: %v", err)
	}
}

// This file is the single definition of which fields a DecisionRecord
// carries for every audit-side treatment of decision content: the
// fingerprint's raw canonical encoder, the valid-UTF-8 test that chooses
// between the JSON and raw fingerprint families, the archive writer and
// reader, and the detaching copy that keeps stored records independent of
// caller slices. Each of those walks the one table below instead of naming
// the fields itself, so the fields and their order mean the same thing
// everywhere. Adding or changing a decision field here reaches
// fingerprinting, the UTF-8 decision, archiving, unarchiving and cloning at
// once; no audit path can keep a stale list of its own.
//
// The table order is part of the wire and fingerprint contract: it is the
// historical decision field order — the two organization names, the subject,
// the resource, the action, then the decision itself — and the archive
// mirrors it field for field. Authorization itself (org.go) is intentionally
// not driven from this table: Roles participates here as a saved request
// field even though org policy evaluation never matches on it.
package darksafe

import "unicode/utf8"

// decisionFieldKind says how one DecisionRecord field participates in
// fingerprinting and archiving.
type decisionFieldKind int

const (
	// decisionFieldString is a string field written from its exact bytes by
	// both the fingerprint encoder and the archive.
	decisionFieldString decisionFieldKind = iota
	// decisionFieldStringList is a string slice whose nil-versus-empty
	// shape and element order are preserved explicitly by both encoders.
	decisionFieldStringList
	// decisionFieldBool is a boolean field. It has no UTF-8 representation,
	// so the valid-UTF-8 scan skips it while both encoders write it.
	decisionFieldBool
	// decisionFieldInt is a non-negative integer field (the policy version
	// the decision used). It has no UTF-8 representation either.
	decisionFieldInt
)

// decisionFieldSpec locates one DecisionRecord leaf field. The accessors
// used depend on the kind: string fields use getString/setString, list
// fields getList/setList, booleans getBool/setBool and integers
// getInt/setInt. A field appears in decisionFields exactly once, and that
// entry is the only place its struct member is named.
type decisionFieldSpec struct {
	kind decisionFieldKind
	// groupTag, when non-zero, is a nesting marker the fingerprint encoder
	// emits immediately before this field, opening the subject, resource or
	// decision group exactly where the historical encoding placed it. The
	// archive has no group markers and ignores this.
	groupTag  fingerprintTag
	getString func(*DecisionRecord) string
	setString func(*DecisionRecord, string)
	getList   func(*DecisionRecord) []string
	setList   func(*DecisionRecord, []string)
	getBool   func(*DecisionRecord) bool
	setBool   func(*DecisionRecord, bool)
	getInt    func(*DecisionRecord) int
	setInt    func(*DecisionRecord, int)
}

// decisionFields lists every DecisionRecord leaf field in fingerprint
// canonical order, which the archive reproduces exactly. The subject group
// opens at Subject.ID, the resource group at Resource.ID and the decision
// group at Decision.Allowed, matching the historical nesting markers.
var decisionFields = [...]decisionFieldSpec{
	{
		kind:      decisionFieldString,
		getString: func(d *DecisionRecord) string { return d.Request.SubjectOrg },
		setString: func(d *DecisionRecord, s string) { d.Request.SubjectOrg = s },
	},
	{
		kind:      decisionFieldString,
		getString: func(d *DecisionRecord) string { return d.Request.ResourceOrg },
		setString: func(d *DecisionRecord, s string) { d.Request.ResourceOrg = s },
	},
	{
		kind:      decisionFieldString,
		groupTag:  tagSubject,
		getString: func(d *DecisionRecord) string { return d.Request.Subject.ID },
		setString: func(d *DecisionRecord, s string) { d.Request.Subject.ID = s },
	},
	{
		kind:      decisionFieldString,
		getString: func(d *DecisionRecord) string { return d.Request.Subject.Kind },
		setString: func(d *DecisionRecord, s string) { d.Request.Subject.Kind = s },
	},
	{
		kind:    decisionFieldStringList,
		getList: func(d *DecisionRecord) []string { return d.Request.Subject.Roles },
		setList: func(d *DecisionRecord, l []string) { d.Request.Subject.Roles = l },
	},
	{
		kind:    decisionFieldBool,
		getBool: func(d *DecisionRecord) bool { return d.Request.Subject.Disabled },
		setBool: func(d *DecisionRecord, v bool) { d.Request.Subject.Disabled = v },
	},
	{
		kind:      decisionFieldString,
		groupTag:  tagResource,
		getString: func(d *DecisionRecord) string { return d.Request.Resource.ID },
		setString: func(d *DecisionRecord, s string) { d.Request.Resource.ID = s },
	},
	{
		kind:      decisionFieldString,
		getString: func(d *DecisionRecord) string { return d.Request.Resource.Scope },
		setString: func(d *DecisionRecord, s string) { d.Request.Resource.Scope = s },
	},
	{
		kind:      decisionFieldString,
		getString: func(d *DecisionRecord) string { return d.Request.Action },
		setString: func(d *DecisionRecord, s string) { d.Request.Action = s },
	},
	{
		kind:     decisionFieldBool,
		groupTag: tagDecision,
		getBool:  func(d *DecisionRecord) bool { return d.Decision.Allowed },
		setBool:  func(d *DecisionRecord, v bool) { d.Decision.Allowed = v },
	},
	{
		kind:      decisionFieldString,
		getString: func(d *DecisionRecord) string { return d.Decision.Reason },
		setString: func(d *DecisionRecord, s string) { d.Decision.Reason = s },
	},
	{
		kind:    decisionFieldStringList,
		getList: func(d *DecisionRecord) []string { return d.Decision.Matched },
		setList: func(d *DecisionRecord, l []string) { d.Decision.Matched = l },
	},
	{
		kind:   decisionFieldInt,
		getInt: func(d *DecisionRecord) int { return d.Decision.Version },
		setInt: func(d *DecisionRecord, v int) { d.Decision.Version = v },
	},
}

// decisionRecordHasNonUTF8 reports whether any string or list element of d
// carries bytes that are not valid UTF-8. It ranges the single field table,
// so its idea of which decision strings the fingerprint protects can never
// diverge from the fields the encoders write. Boolean and integer fields
// cannot carry a raw byte and are skipped by kind rather than listed
// separately.
func decisionRecordHasNonUTF8(d *DecisionRecord) bool {
	for i := range decisionFields {
		f := &decisionFields[i]
		switch f.kind {
		case decisionFieldString:
			if !utf8.ValidString(f.getString(d)) {
				return true
			}
		case decisionFieldStringList:
			for _, s := range f.getList(d) {
				if !utf8.ValidString(s) {
					return true
				}
			}
		}
	}
	return false
}

// cloneDecisionLists detaches every string list field of src into dst,
// preserving each list's nil-versus-empty shape. It ranges the single field
// table, so a list field added to the record is detached here without this
// function changing.
func cloneDecisionLists(dst, src *DecisionRecord) {
	for i := range decisionFields {
		f := &decisionFields[i]
		if f.kind == decisionFieldStringList {
			f.setList(dst, cloneStrings(f.getList(src)))
		}
	}
}

// This file is the single definition of which fields a Policy carries for
// every audit-side treatment of policy content: the fingerprint's raw
// canonical encoder, the valid-UTF-8 test that chooses between the JSON and
// raw fingerprint families, and the archive writer and reader. Each of
// those walks the one table below instead of naming the fields itself, so
// the fields and their order mean the same thing everywhere. Adding or
// changing a policy field here reaches fingerprinting, the UTF-8 decision,
// archiving and unarchiving at once; no audit path can keep a stale list of
// its own.
//
// The table order is part of the wire and fingerprint contract: it is the
// historical fingerprint field order, and the archive mirrors it field for
// field. Authorization itself (org.go) is intentionally not driven from
// this table.
package darksafe

import "unicode/utf8"

// policyFieldKind says how one Policy field participates in fingerprinting
// and archiving.
type policyFieldKind int

const (
	// policyFieldString is a string field written unconditionally by both
	// the fingerprint encoder and the archive.
	policyFieldString policyFieldKind = iota
	// policyFieldOptionalString is a string field carried by the legacy JSON
	// fingerprint family under an omitempty tag. The raw fingerprint encoder
	// appends it only when non-empty, so empty values keep the exact legacy
	// fingerprint bytes; the archive always writes it, including the empty
	// value, so the field still round trips on its own.
	policyFieldOptionalString
	// policyFieldBool is a boolean field. It has no UTF-8 representation, so
	// the valid-UTF-8 scan skips it while both encoders write it.
	policyFieldBool
)

// policyFieldSpec locates one Policy field. The string accessors are set for
// policyFieldString and policyFieldOptionalString; the bool accessors are
// set for policyFieldBool. A field appears in policyFields exactly once, and
// that entry is the only place its struct member is named.
type policyFieldSpec struct {
	kind      policyFieldKind
	getString func(Policy) string
	setString func(*Policy, string)
	getBool   func(Policy) bool
	setBool   func(*Policy, bool)
}

// policyFields lists every Policy field in fingerprint canonical order,
// which the archive reproduces exactly. Recursive (the sole boolean) sits
// between Effect and ResourceID exactly as it always has; ResourceID is the
// one field that is optional for fingerprints but always archived.
var policyFields = [...]policyFieldSpec{
	{
		kind:      policyFieldString,
		getString: func(p Policy) string { return p.ID },
		setString: func(p *Policy, s string) { p.ID = s },
	},
	{
		kind:      policyFieldString,
		getString: func(p Policy) string { return p.Subject },
		setString: func(p *Policy, s string) { p.Subject = s },
	},
	{
		kind:      policyFieldString,
		getString: func(p Policy) string { return p.Action },
		setString: func(p *Policy, s string) { p.Action = s },
	},
	{
		kind:      policyFieldString,
		getString: func(p Policy) string { return p.Scope },
		setString: func(p *Policy, s string) { p.Scope = s },
	},
	{
		kind:      policyFieldString,
		getString: func(p Policy) string { return string(p.Effect) },
		setString: func(p *Policy, s string) { p.Effect = Effect(s) },
	},
	{
		kind:    policyFieldBool,
		getBool: func(p Policy) bool { return p.Recursive },
		setBool: func(p *Policy, v bool) { p.Recursive = v },
	},
	{
		kind:      policyFieldOptionalString,
		getString: func(p Policy) string { return p.ResourceID },
		setString: func(p *Policy, s string) { p.ResourceID = s },
	},
}

// policyHasNonUTF8 reports whether any string field of p carries bytes that
// are not valid UTF-8. It ranges the single field table, so its idea of
// which policy strings the fingerprint protects can never diverge from the
// fields the encoders write. A boolean field cannot carry a raw byte and is
// skipped by kind rather than listed separately.
func policyHasNonUTF8(p Policy) bool {
	for i := range policyFields {
		f := &policyFields[i]
		if f.kind == policyFieldBool {
			continue
		}
		if !utf8.ValidString(f.getString(p)) {
			return true
		}
	}
	return false
}

// This file is the single definition of which fields a PolicyChange carries
// for every audit-side treatment of policy-change content: the fingerprint's
// raw canonical encoder, the valid-UTF-8 test that chooses between the JSON
// and raw fingerprint families, the archive writer and reader, and the
// detaching copy that keeps stored records independent of caller slices. Each
// of those walks the one table below instead of naming the fields itself, so
// the fields and their order mean the same thing everywhere. Adding or
// changing a policy-change field here reaches fingerprinting, the UTF-8
// decision, archiving, unarchiving and cloning at once; no audit path can
// keep a stale list of its own.
//
// The table order is part of the wire and fingerprint contract: it is the
// historical policy-change field order — the new version, the full policy
// set, the source version, then the rollback marker — and the archive
// mirrors it field for field. Publishing and rollback themselves (org.go)
// are intentionally not driven from this table.
package darksafe

// changeFieldKind says how one PolicyChange field participates in
// fingerprinting and archiving.
type changeFieldKind int

const (
	// changeFieldInt is a non-negative integer field (a policy version
	// number). It has no UTF-8 representation, so the valid-UTF-8 scan skips
	// it while both encoders write it.
	changeFieldInt changeFieldKind = iota
	// changeFieldPolicyList is the full policy set of the new version. Its
	// nil-versus-empty shape and element order are preserved explicitly by
	// both encoders, and its policy strings are protected by the valid-UTF-8
	// scan through the single policy field table.
	changeFieldPolicyList
	// changeFieldBool is a boolean field (the rollback marker). It has no
	// UTF-8 representation either.
	changeFieldBool
)

// changeFieldSpec locates one PolicyChange field. The accessors used depend
// on the kind: integer fields use getInt/setInt, the policy list uses
// getPolicies/setPolicies and booleans getBool/setBool. A field appears in
// changeFields exactly once, and that entry is the only place its struct
// member is named.
type changeFieldSpec struct {
	kind        changeFieldKind
	getInt      func(*PolicyChange) int
	setInt      func(*PolicyChange, int)
	getPolicies func(*PolicyChange) []Policy
	setPolicies func(*PolicyChange, []Policy)
	getBool     func(*PolicyChange) bool
	setBool     func(*PolicyChange, bool)
}

// changeFields lists every PolicyChange field in fingerprint canonical
// order, which the archive reproduces exactly: Version, Policies,
// SourceVersion, RolledBack, exactly as the historical encoding placed them.
var changeFields = [...]changeFieldSpec{
	{
		kind:   changeFieldInt,
		getInt: func(c *PolicyChange) int { return c.Version },
		setInt: func(c *PolicyChange, v int) { c.Version = v },
	},
	{
		kind:        changeFieldPolicyList,
		getPolicies: func(c *PolicyChange) []Policy { return c.Policies },
		setPolicies: func(c *PolicyChange, l []Policy) { c.Policies = l },
	},
	{
		kind:   changeFieldInt,
		getInt: func(c *PolicyChange) int { return c.SourceVersion },
		setInt: func(c *PolicyChange, v int) { c.SourceVersion = v },
	},
	{
		kind:    changeFieldBool,
		getBool: func(c *PolicyChange) bool { return c.RolledBack },
		setBool: func(c *PolicyChange, v bool) { c.RolledBack = v },
	},
}

// changeHasNonUTF8 reports whether any policy string the change carries
// holds bytes that are not valid UTF-8. It ranges the single field table, so
// its idea of which change content the fingerprint protects can never
// diverge from the fields the encoders write. Integer and boolean fields
// cannot carry a raw byte and are skipped by kind rather than listed
// separately; which strings inside one policy are protected remains decided
// by the single policy field table alone.
func changeHasNonUTF8(c *PolicyChange) bool {
	for i := range changeFields {
		f := &changeFields[i]
		if f.kind != changeFieldPolicyList {
			continue
		}
		for _, p := range f.getPolicies(c) {
			if policyHasNonUTF8(p) {
				return true
			}
		}
	}
	return false
}

// cloneChangeLists detaches every policy list field of src into dst,
// preserving each list's nil-versus-empty shape exactly as clonePolicies
// defines it. It ranges the single field table, so a policy list added to
// the payload is detached here without this function changing.
func cloneChangeLists(dst, src *PolicyChange) {
	for i := range changeFields {
		f := &changeFields[i]
		if f.kind == changeFieldPolicyList {
			f.setPolicies(dst, clonePolicies(f.getPolicies(src)))
		}
	}
}

